#include <iostream>
#include <vector>

int main() {
    using namespace std;
    int N, K;
    cin >> N >> K;

    vector<int> path(N);
    [N, K](this auto self, int index, int sum, vector<int>& path) -> void {
        if (index + 1 == N) { // 最後の 1 項になったら
            if ((K - sum) % N == 0) { // 合計を K にできるときのみ
                path.back() = (K - sum) / N;
                for (int p : path) // 出力
                    cout << p << ' ';
                cout << '\n';
            }
            return;
        } 

        // i 項目を決めて再帰
        for (int i = 0; sum + i * (index + 1) <= K; ++i) {
            path[index] = i;
            self(index + 1, sum + i * (index + 1), path);
        }
    }(0, 0, path);

    return 0;
}
N, K = map(int, input().split())

def dfs(i, s, A):
    if i == N - 1: # 最後の 1 項になったら
        if (K - s) % N == 0: # 合計を K にできるときのみ
            A[i] = (K - s) // N
            print(' '.join(str(a) for a in A)) # 出力
        return

    # i 項目を決めて再帰
    for x in range(0, (K - s) // (i + 1) + 1):
        A[i] = x
        dfs(i + 1, s + x * (i + 1), A)

